import torch,hydra
torch.set_num_threads(4)
from omegaconf import OmegaConf
OmegaConf.register_new_resolver('eval',eval,replace=True)
from napari_dare3d import _api as api
from dare3d.metrics.inference import segmentation_inference
from unittest.mock import patch
cfg=api._load_inference_cfg(str(cfgdir),str(movies['movie_I2'][0].parent),'gpu',checkpoint_path=str(ckpt))
ds=large_stack(lambda:api._build_dataset(cfg,'segmentation'))
# Probe only the first inference sequence; other settings stay at the existing overlap=.5 baseline.
ds.movies_im[0]=ds.movies_im[0][:3]
arch=tifffile.memmap(legacy/'movie_I2.tif')[2]
baseline=tifffile.memmap(out/'movie_I2_offline_overlap.tif')[2]
def cmp(a,b):
    a=np.asarray(a,np.float32); b=np.asarray(b,np.float32)
    return {'mean_abs':float(np.abs(a-b).mean()),'max_abs':float(np.abs(a-b).max()),'binary_disagreement_half':int(np.count_nonzero((a>.5)!=(b>.5))),'correlation':float(np.corrcoef(a.reshape(-1)[::7],b.reshape(-1)[::7])[0,1]),'above_half':int(np.count_nonzero(a>.5))}
for label,path,cpu in [('selected_cpu_resize',ckpt,True),('legacy_last_gpu_resize',legacy/'checkpoints/last.ckpt',False)]:
    cfg.ckpt_path=str(path)
    model=api._build_model(cfg,torch.device('cuda:0'),stage='segmentation')
    print('BEGIN PROBE',label,flush=True)
    begin=time.perf_counter()
    if cpu:
        def prep(i,start,end,device):
            return torch.tensor(ds.preprocess_sample(i,start,end),device=device)
        with patch.object(ds,'preprocess_sample_gpu',side_effect=prep):
            pred=large_stack(lambda:segmentation_inference(ds,model,torch.device('cuda:0'),128,4,overlap=.5))[0]
    else:
        pred=large_stack(lambda:segmentation_inference(ds,model,torch.device('cuda:0'),128,4,overlap=.5))[0]
    tifffile.imwrite(out/('movie_I2_'+label+'_probe.tif'),pred,metadata={'axes':'TZYX'})
    record={'checkpoint':path,'sha256':sha(path),'probe_frames':[0,1,2],'prediction_frame':2,'cpu_preprocessing_only_changed':cpu,'overlap':.5,'batch_size':4,'elapsed_seconds':time.perf_counter()-begin,'vs_archived':cmp(pred[2],arch),'vs_selected_gpu':cmp(pred[2],baseline)}
    save('movie_I2_'+label+'_probe.json',record);print(json.dumps(record,default=plain),flush=True)
    del model,pred;gc.collect();torch.cuda.empty_cache()
